import unittest
from token_codec import decode_token

class Tokens(unittest.TestCase):
    def test_padding_and_binary(self):
        for text, data in [('',b''),('Zg',b'f'),('Zm8',b'fo'),('Zm9v',b'foo'),('-_8',bytes([251,255]))]:
            self.assertEqual(decode_token(text),data)
    def test_rejected(self):
        for text in ['A','AAAAA','Zg=','Z g','Zg\n','+w','/w','éA','$$']:
            with self.subTest(text=text):
                with self.assertRaises(ValueError): decode_token(text)

if __name__ == '__main__':
    unittest.main()

