import base64
import re

def decode_token(token):
    if re.fullmatch(r'[A-Za-z0-9_-]*', token) is None or len(token) % 4 == 1:
        raise ValueError('invalid token')
    return base64.b64decode(token + '=' * (-len(token) % 4), altchars=b'-_', validate=True)

